"use client";

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/evilcharts; derived here under Apache-2.0.
 */

import {
	type ChartConfig,
	ChartContainer,
	LoadingIndicator,
} from "../ui/chart";
import {
	ChartLegend,
	ChartLegendContent,
	type ChartLegendVariant,
} from "../ui/legend";
import {
	ChartTooltip,
	ChartTooltipContent,
	type TooltipRoundness,
	type TooltipVariant,
} from "../ui/tooltip";
import { type ComponentProps, type ReactNode, useMemo } from "react";
import { Cell, Pie, PieChart as RechartsPieChart } from "recharts";
import type { ValueType } from "recharts/types/component/DefaultTooltipContent";

// A donut slice: `key` must exist in the chart config (it drives the slice's
// color + label), `value` is the slice's share.
export type DonutSlice = {
	key: string;
	value: number;
};

type EvilDonutChartProps = {
	config: ChartConfig; // slice colors + labels, keyed by DonutSlice.key
	data: DonutSlice[]; // slices; zero/negative values are dropped (they break recharts pies)
	className?: string; // extra classes for the chart container
	chartProps?: ComponentProps<typeof RechartsPieChart>; // escape hatch for the raw Recharts chart
	innerRadius?: number | string; // hole size — the "donut" part
	outerRadius?: number | string;
	paddingAngle?: number; // gap between slices, in degrees
	cornerRadius?: number; // rounding of each slice's ends
	centerLabel?: ReactNode; // headline rendered in the hole (e.g. total cost)
	centerSubLabel?: ReactNode; // smaller line under the headline
	showLegend?: boolean;
	legendVariant?: ChartLegendVariant;
	tooltipVariant?: TooltipVariant;
	tooltipRoundness?: TooltipRoundness;
	// Formats the numeric value shown in the tooltip rows.
	valueFormatter?: (value: ValueType, key: string) => ReactNode;
	isLoading?: boolean;
};

/**
 * Donut (pie-with-a-hole) chart in the evilcharts pattern: colors and labels
 * come from a `ChartConfig` (CSS vars scoped by `ChartStyle`), and it reuses
 * the shared tooltip + legend. Single-series — each data row is one slice.
 */
export function EvilDonutChart({
	config,
	data,
	className,
	chartProps,
	innerRadius = "62%",
	outerRadius = "85%",
	paddingAngle = 2,
	cornerRadius = 4,
	centerLabel,
	centerSubLabel,
	showLegend = false,
	legendVariant,
	tooltipVariant,
	tooltipRoundness,
	valueFormatter,
	isLoading = false,
}: EvilDonutChartProps) {
	// Zero/negative slices render as invisible degenerate sectors in recharts
	// (and still show up in tooltips/legend) — drop them up front.
	const slices = useMemo(() => data.filter((d) => d.value > 0), [data]);

	return (
		<div className="relative flex min-h-0 w-full flex-1 flex-col">
			<ChartContainer className={className} config={config}>
				<RechartsPieChart accessibilityLayer {...chartProps}>
					<ChartTooltip
						cursor={false}
						content={
							<ChartTooltipContent
								hideLabel
								nameKey="key"
								variant={tooltipVariant}
								roundness={tooltipRoundness}
								valueFormatter={
									valueFormatter
										? (value, dataKey) => valueFormatter(value, dataKey)
										: undefined
								}
							/>
						}
					/>
					<Pie
						data={slices}
						dataKey="value"
						nameKey="key"
						innerRadius={innerRadius}
						outerRadius={outerRadius}
						paddingAngle={paddingAngle}
						cornerRadius={cornerRadius}
						strokeWidth={0}
						isAnimationActive={false}
					>
						{slices.map((slice) => (
							<Cell key={slice.key} fill={`var(--color-${slice.key}-0)`} />
						))}
					</Pie>
					{showLegend && (
						<ChartLegend
							verticalAlign="bottom"
							// Span the full width so the wrapped, centered legend stays
							// centered — otherwise Recharts sizes the wrapper to the
							// content's single-line width and anchors it off-center.
							wrapperStyle={{ left: 0, width: "100%" }}
							content={
								<ChartLegendContent align="center" variant={legendVariant} />
							}
						/>
					)}
				</RechartsPieChart>
			</ChartContainer>
			<LoadingIndicator isLoading={isLoading} />
			{(centerLabel != null || centerSubLabel != null) && (
				<div
					className={
						// Offset the overlay up by half the legend's height so it stays
						// centered on the donut hole, not the whole container.
						showLegend
							? "pointer-events-none absolute inset-0 bottom-8 flex flex-col items-center justify-center"
							: "pointer-events-none absolute inset-0 flex flex-col items-center justify-center"
					}
				>
					{centerLabel != null && (
						<span className="text-foreground text-xl font-semibold tabular-nums">
							{centerLabel}
						</span>
					)}
					{centerSubLabel != null && (
						<span className="text-muted-foreground text-xs">
							{centerSubLabel}
						</span>
					)}
				</div>
			)}
		</div>
	);
}

"use client";

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/evilcharts; derived here under Apache-2.0.
 */

import { cn } from "../../../lib/utils";
import * as React from "react";
import * as RechartsPrimitive from "recharts";

// Format: { THEME_NAME: CSS_SELECTOR }
const THEMES = { light: "", dark: ".dark" } as const;

type ThemeKey = keyof typeof THEMES;

// All Keys are optional at first
type ThemeColorsBase = {
	[K in ThemeKey]?: string[];
};

// Require at least one theme key
type AtLeastOneThemeColor = {
	[K in ThemeKey]: Required<Pick<ThemeColorsBase, K>> &
		Partial<Omit<ThemeColorsBase, K>>;
}[ThemeKey];

const VALID_THEME_KEYS = Object.keys(THEMES) as ThemeKey[];

// Validation for chart config colors at runtime
function validateChartConfigColors(config: ChartConfig): void {
	for (const [key, value] of Object.entries(config)) {
		if (value.colors) {
			const hasValidThemeKey = VALID_THEME_KEYS.some(
				(themeKey) => value.colors?.[themeKey] !== undefined,
			);

			if (!hasValidThemeKey) {
				throw new Error(
					`[EvilCharts] Invalid chart config for "${key}": colors object must have at least one theme key (${VALID_THEME_KEYS.join(", ")}). Received empty object or invalid keys.`,
				);
			}
		}
	}
}

export type ChartConfig = Record<
	string,
	{
		label?: React.ReactNode;
		icon?: React.ComponentType;
		colors?: AtLeastOneThemeColor;
	}
>;

interface ChartContextProps {
	config: ChartConfig;
}

const ChartContext = React.createContext<ChartContextProps | null>(null);

export function useChart() {
	const context = React.useContext(ChartContext);

	if (!context) {
		throw new Error("useChart must be used within a <ChartContainer />");
	}

	return context;
}

interface ChartContainerProps
	extends Omit<React.ComponentProps<"div">, "children">,
		Pick<
			React.ComponentProps<typeof RechartsPrimitive.ResponsiveContainer>,
			| "initialDimension"
			| "aspect"
			| "debounce"
			| "minHeight"
			| "minWidth"
			| "maxHeight"
			| "height"
			| "width"
			| "onResize"
			| "children"
		> {
	config: ChartConfig;
	innerResponsiveContainerStyle?: React.ComponentProps<
		typeof RechartsPrimitive.ResponsiveContainer
	>["style"];
	/** Optional content rendered below the chart (e.g. EvilBrush) */
	footer?: React.ReactNode;
	/** Dims the plot while a refetch keeps stale data on screen. The dim eases
	 * in after a short transition delay, so fetches that resolve quickly never
	 * visibly flash it. */
	isUpdating?: boolean;
}

function ChartContainer({
	id,
	config,
	initialDimension = { width: 320, height: 200 },
	// Coalesce resize storms into a single re-render. Layout-driven tweens (the
	// Foggy panel animating its width, dragging its resize handle) fire the
	// ResizeObserver every frame; without a debounce each chart fully re-renders
	// its SVG per frame, which is what tanks the FPS on chart-heavy pages.
	debounce = 100,
	className,
	children,
	footer,
	isUpdating = false,
	...props
}: Readonly<ChartContainerProps>) {
	const uniqueId = React.useId();
	const chartId = `chart-${id ?? uniqueId.replace(/:/g, "")}`;

	// Validate chart config at runtime
	validateChartConfigColors(config);

	return (
		<ChartContext.Provider value={{ config }}>
			<div
				data-slot="chart"
				data-chart={chartId}
				className={cn(
					"min-h-0 w-full flex-1",
					"[&_.recharts-yAxis-tick-labels_.recharts-cartesian-axis-tick-value]:tabular-nums [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-muted-foreground/20 dark:[&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-muted-foreground/50 [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border relative flex flex-col justify-center text-xs [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-hidden [&_.recharts-sector]:outline-hidden [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-surface]:outline-hidden [&_*:focus]:outline-none [&_*:focus-visible]:outline-none",
					!footer && "aspect-video",
					className,
				)}
				{...props}
			>
				<ChartStyle id={chartId} config={config} />
				<RechartsPrimitive.ResponsiveContainer
					className={cn(
						"min-h-0 w-full flex-1 transition-opacity",
						isUpdating ? "opacity-50 delay-150 duration-300" : "duration-150",
					)}
					initialDimension={initialDimension}
					debounce={debounce}
				>
					{children}
				</RechartsPrimitive.ResponsiveContainer>
				{footer}
			</div>
		</ChartContext.Provider>
	);
}

function LoadingIndicator({ isLoading }: { isLoading: boolean }) {
	if (!isLoading) {
		return null;
	}

	return (
		<div className="pointer-events-none absolute inset-0 z-20 flex items-center justify-center">
			<div className="text-primary bg-background flex items-center justify-center gap-2 rounded-md border px-2 py-0.5 text-sm">
				<div className="border-border border-t-primary h-3 w-3 animate-spin rounded-full border" />
				<span>Loading</span>
			</div>
		</div>
	);
}

// Distribute colors evenly across slots, extra slots go to last color(s)
// Example: 2 colors for 4 slots → [red, red, pink, pink]
// Example: 3 colors for 4 slots → [red, pink, blue, blue]
function distributeColors(colorsArray: string[], maxCount: number): string[] {
	const availableCount = colorsArray.length;
	if (availableCount >= maxCount) {
		return colorsArray.slice(0, maxCount);
	}

	const result: string[] = [];
	const baseSlots = Math.floor(maxCount / availableCount);
	const extraSlots = maxCount % availableCount;

	// First (availableCount - extraSlots) colors get baseSlots each
	// Last extraSlots colors get (baseSlots + 1) each
	for (let colorIdx = 0; colorIdx < availableCount; colorIdx++) {
		const isExtraColor = colorIdx >= availableCount - extraSlots;
		const slotsForThisColor = baseSlots + (isExtraColor ? 1 : 0);
		for (let j = 0; j < slotsForThisColor; j++) {
			result.push(colorsArray[colorIdx]);
		}
	}

	return result;
}

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
	const colorConfig = Object.entries(config).filter(
		([, config]) => config.colors,
	);

	if (!colorConfig.length) {
		return null;
	}

	const generateCssVars = (theme: keyof typeof THEMES) =>
		colorConfig
			.flatMap(([key, itemConfig]) => {
				const colorsArray = itemConfig.colors?.[theme];
				if (
					!colorsArray ||
					!Array.isArray(colorsArray) ||
					colorsArray.length === 0
				) {
					return [];
				}

				// Get max count across all themes for this key
				const maxCount = getColorsCount(itemConfig);

				// Distribute colors evenly across all required slots
				const distributedColors = distributeColors(colorsArray, maxCount);

				return distributedColors.map(
					(color, index) => `  --color-${key}-${index}: ${color};`,
				);
			})
			.filter(Boolean)
			.join("\n");

	const css = Object.entries(THEMES)
		.map(
			([theme, prefix]) =>
				`${prefix} [data-chart=${id}] {\n${generateCssVars(theme as keyof typeof THEMES)}\n}`,
		)
		.join("\n");

	return <style dangerouslySetInnerHTML={{ __html: css }} />;
};

// Helper to extract item config from a payload.
export function getPayloadConfigFromPayload(
	config: ChartConfig,
	payload: unknown,
	key: string,
) {
	if (typeof payload !== "object" || payload === null) {
		return undefined;
	}

	const payloadPayload =
		"payload" in payload &&
		typeof payload.payload === "object" &&
		payload.payload !== null
			? payload.payload
			: undefined;

	let configLabelKey: string = key;

	if (
		key in payload &&
		typeof payload[key as keyof typeof payload] === "string"
	) {
		configLabelKey = payload[key as keyof typeof payload] as string;
	} else if (
		payloadPayload &&
		key in payloadPayload &&
		typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
	) {
		configLabelKey = payloadPayload[
			key as keyof typeof payloadPayload
		] as string;
	}

	return configLabelKey in config ? config[configLabelKey] : config[key];
}

// Format values to percent for expanded charts
function axisValueToPercentFormatter(value: number) {
	return `${Math.round(value * 100).toFixed(0)}%`;
}

// Snap a value up to the next "nice" number (1/1.2/1.5/2/2.5/3/4/5/6/8 × 10ⁿ).
// Used as the numeric y-axis max so live data refreshes only move the axis when
// the data actually outgrows the current nice bound — no per-refresh jitter.
function niceCeil(value: number): number {
	if (!Number.isFinite(value) || value <= 0) return 1;
	const exp = 10 ** Math.floor(Math.log10(value));
	const mantissa = value / exp;
	const steps = [1, 1.2, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10];
	const step = steps.find((s) => s >= mantissa - 1e-9) ?? 10;
	return step * exp;
}

// Default numeric y-axis domain: zero-based with a nice, stable upper bound.
const niceDomain: [number, (dataMax: number) => number] = [
	0,
	(dataMax: number) => niceCeil(dataMax),
];

// Get max colors count across all themes for a config entry
function getColorsCount(config: ChartConfig[string]): number {
	if (!config.colors) return 1;
	const counts = VALID_THEME_KEYS.map(
		(theme) => config.colors?.[theme]?.length ?? 0,
	);
	return Math.max(...counts, 1);
}

// Generate random loading data for skeleton/loading state
// min/max represent percentage of the range (0-100), defaults to 20-80 for realistic look
export const getLoadingData = (points = 10, min = 0, max = 70) => {
	const range = max - min;
	return Array.from({ length: points }, () => ({
		loading: Math.floor(Math.random() * range) + min,
	}));
};

export {
	ChartContainer,
	ChartStyle,
	axisValueToPercentFormatter,
	LoadingIndicator,
	getColorsCount,
	niceCeil,
	niceDomain,
};

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/evilcharts; derived here under Apache-2.0.
 */
import {
	getColorsCount,
	getPayloadConfigFromPayload,
	useChart,
} from "./chart";
import { cn } from "../../../lib/utils";
import type * as React from "react";
import * as RechartsPrimitive from "recharts";

type ChartLegendVariant =
	| "square"
	| "circle"
	| "circle-outline"
	| "rounded-square"
	| "rounded-square-outline"
	| "vertical-bar"
	| "horizontal-bar";

function ChartLegendContent({
	className,
	hideIcon = false,
	nameKey,
	payload,
	verticalAlign,
	align = "right",
	selected = null,
	onSelectChange,
	isClickable,
	variant = "rounded-square",
}: React.ComponentProps<"div"> & {
	hideIcon?: boolean;
	nameKey?: string;
	selected?: string | null;
	isClickable?: boolean;
	onSelectChange?: (selected: string | null) => void;
	variant?: ChartLegendVariant;
} & RechartsPrimitive.DefaultLegendContentProps) {
	const { config } = useChart();

	if (!payload?.length) {
		return null;
	}

	return (
		<div
			className={cn(
				"flex flex-wrap items-center gap-x-4 gap-y-1.5 select-none",
				align === "left" && "justify-start",
				align === "center" && "justify-center",
				align === "right" && "justify-end",
				verticalAlign === "top" ? "pb-4" : "pt-4",
				className,
			)}
		>
			{payload
				.filter((item) => item.type !== "none")
				.map((item) => {
					// For pie charts, item.value contains the sector name (e.g., "chrome")
					// For radial charts, the name is in item.payload[nameKey]
					// For other charts, item.dataKey contains the series name (e.g., "desktop")
					const payloadName =
						nameKey && item.payload
							? (item.payload as Record<string, unknown>)[nameKey]
							: undefined;
					const key = `${payloadName ?? item.value ?? item.dataKey ?? "value"}`;
					const itemConfig = getPayloadConfigFromPayload(config, item, key);
					const isSelected = selected === null || selected === key;

					// Get colors count for this item to determine gradient vs solid
					const colorsCount = itemConfig ? getColorsCount(itemConfig) : 1;

					return (
						<div
							key={key}
							className={cn(
								"[&>svg]:text-muted-foreground flex items-center gap-1.5 transition-opacity [&>svg]:h-3 [&>svg]:w-3",
								!isSelected && "opacity-30",
								isClickable && "cursor-pointer",
							)}
							onClick={() => {
								if (!isClickable) return;

								onSelectChange?.(selected === key ? null : key);
							}}
						>
							{itemConfig?.icon && !hideIcon ? (
								<itemConfig.icon />
							) : (
								<LegendIndicator
									variant={variant}
									dataKey={key}
									colorsCount={colorsCount}
								/>
							)}
							{itemConfig?.label}
						</div>
					);
				})}
		</div>
	);
}

// ---------------------------------------------------------------------------
// Legend indicator — each variant gets its own branch so future variants
// can diverge freely in markup & style.
// ---------------------------------------------------------------------------

function LegendIndicator({
	variant,
	dataKey,
	colorsCount,
}: {
	variant: ChartLegendVariant;
	dataKey: string;
	colorsCount: number;
}) {
	const fillStyle = getLegendFillStyle(dataKey, colorsCount);
	const outlineStyle = getLegendOutlineStyle(dataKey, colorsCount);

	switch (variant) {
		case "square":
			return <div className="h-2 w-2 shrink-0" style={fillStyle} />;

		case "circle":
			return (
				<div className="h-2 w-2 shrink-0 rounded-full" style={fillStyle} />
			);

		case "circle-outline":
			return (
				<div
					className="h-2.5 w-2.5 shrink-0 rounded-full p-[1.5px]"
					style={outlineStyle}
				/>
			);

		case "vertical-bar":
			return (
				<div className="h-3 w-1 shrink-0 rounded-[2px]" style={fillStyle} />
			);

		case "horizontal-bar":
			return (
				<div className="h-1 w-3 shrink-0 rounded-[2px]" style={fillStyle} />
			);

		case "rounded-square-outline":
			return (
				<div
					className="h-2.5 w-2.5 shrink-0 rounded-[3px] p-[1.5px]"
					style={outlineStyle}
				/>
			);

		case "rounded-square":
		default:
			return (
				<div className="h-2 w-2 shrink-0 rounded-[2px]" style={fillStyle} />
			);
	}
}

// ---------------------------------------------------------------------------
// Style helpers
// ---------------------------------------------------------------------------

/** Solid fill / gradient background for filled variants. */
function getLegendFillStyle(
	dataKey: string,
	colorsCount: number,
): React.CSSProperties {
	if (colorsCount <= 1) {
		return { backgroundColor: `var(--color-${dataKey}-0)` };
	}

	const stops = Array.from({ length: colorsCount }, (_, i) => {
		const offset = (i / (colorsCount - 1)) * 100;
		return `var(--color-${dataKey}-${i}) ${offset}%`;
	}).join(", ");

	return { background: `linear-gradient(to right, ${stops})` };
}

/**
 * Outline style for stroke variants.
 * Uses background + mask-composite to punch out the center, leaving only the
 * "border" visible. Works with both solid colors and gradients, and respects
 * border-radius — unlike plain `border-color`.
 */
function getLegendOutlineStyle(
	dataKey: string,
	colorsCount: number,
): React.CSSProperties {
	const maskStyle: React.CSSProperties = {
		WebkitMask:
			"linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)",
		WebkitMaskComposite: "xor",
		mask: "linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)",
		maskComposite: "exclude",
	};

	if (colorsCount <= 1) {
		return {
			backgroundColor: `var(--color-${dataKey}-0)`,
			...maskStyle,
		};
	}

	const stops = Array.from({ length: colorsCount }, (_, i) => {
		const offset = (i / (colorsCount - 1)) * 100;
		return `var(--color-${dataKey}-${i}) ${offset}%`;
	}).join(", ");

	return {
		background: `linear-gradient(to right, ${stops})`,
		...maskStyle,
	};
}

const ChartLegend = RechartsPrimitive.Legend;

export { ChartLegend, ChartLegendContent, type ChartLegendVariant };

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/evilcharts; derived here under Apache-2.0.
 */
import {
	getColorsCount,
	getPayloadConfigFromPayload,
	useChart,
} from "./chart";
import { cn } from "../../../lib/utils";
import * as React from "react";
import * as RechartsPrimitive from "recharts";
import type {
	NameType,
	ValueType,
} from "recharts/types/component/DefaultTooltipContent";

type TooltipRoundness = "sm" | "md" | "lg" | "xl";
type TooltipVariant = "default" | "frosted-glass";

const roundnessMap: Record<TooltipRoundness, string> = {
	sm: "rounded-sm",
	md: "rounded-md",
	lg: "rounded-lg",
	xl: "rounded-xl",
};

const variantMap: Record<TooltipVariant, string> = {
	default: "bg-background",
	"frosted-glass": "bg-background/70 backdrop-blur-sm",
};

function ChartTooltipContent({
	active,
	payload,
	className,
	indicator = "dot",
	hideLabel = false,
	hideIndicator = false,
	label,
	labelFormatter,
	labelClassName,
	formatter,
	valueFormatter,
	reverse = false,
	nameKey,
	labelKey,
	selected,
	roundness = "lg",
	variant = "default",
	hidden = false,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
	React.ComponentProps<"div"> & {
		hideLabel?: boolean;
		hideIndicator?: boolean;
		indicator?: "line" | "dot" | "dashed";
		nameKey?: string;
		labelKey?: string;
		selected?: string | null;
		roundness?: TooltipRoundness;
		variant?: TooltipVariant;
		// Suppresses the tooltip body while keeping the Tooltip mounted — used by
		// synced charts (`syncId`) so only the hovered chart shows content while
		// the others still draw the shared cursor line.
		hidden?: boolean;
		// Formats just the numeric value (the right-hand figure of each row),
		// leaving the color dot, icon, and label layout intact. Also receives the
		// full data row, so e.g. a stacked band chart (which plots deltas) can map
		// back to the absolute value it represents.
		valueFormatter?: (
			value: ValueType,
			dataKey: string,
			payload: Record<string, unknown>,
		) => React.ReactNode;
		// Lists the rows in reverse payload order (e.g. so a stacked p50/p95/p99
		// chart reads p99 → p50 top-to-bottom).
		reverse?: boolean;
	} & Omit<
		RechartsPrimitive.DefaultTooltipContentProps<ValueType, NameType>,
		"accessibilityLayer"
	>) {
	const { config } = useChart();

	const tooltipLabel = React.useMemo(() => {
		if (hideLabel || !payload?.length) {
			return null;
		}

		const [item] = payload;
		const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`;
		const itemConfig = getPayloadConfigFromPayload(config, item, key);
		const value =
			!labelKey && typeof label === "string"
				? (config[label]?.label ?? label)
				: itemConfig?.label;

		if (labelFormatter) {
			return (
				<div className={cn("font-medium", labelClassName)}>
					{labelFormatter(value, payload)}
				</div>
			);
		}

		if (!value) {
			return null;
		}

		return <div className={cn("font-medium", labelClassName)}>{value}</div>;
	}, [
		label,
		labelFormatter,
		payload,
		hideLabel,
		labelClassName,
		config,
		labelKey,
	]);

	if (hidden || !active || !payload?.length) {
		// Empty tooltip - to prevent position getting 0.0 so it doesnt animate tooltip every time from 0.0 origin
		return <span className="p-4" />;
	}

	const nestLabel = payload.length === 1 && indicator !== "dot";

	return (
		<div
			className={cn(
				"border-border/50 grid min-w-32 items-start gap-1.5 border px-2.5 py-1.5 text-xs shadow-xl",
				roundnessMap[roundness],
				variantMap[variant],
				className,
			)}
		>
			{!nestLabel ? tooltipLabel : null}
			<div className="grid gap-1.5">
				{(() => {
					const rows = payload.filter((item) => item.type !== "none");
					return reverse ? rows.slice().reverse() : rows;
				})().map((item, index) => {
					// For pie charts, item.name contains the sector name (e.g., "chrome")
					// For radial charts, the name is in item.payload[nameKey]
					// For other charts, item.name or item.dataKey contains the series name
					const payloadName =
						nameKey && item.payload
							? (item.payload as Record<string, unknown>)[nameKey]
							: undefined;
					const key = `${payloadName ?? item.name ?? item.dataKey ?? "value"}`;
					const itemConfig = getPayloadConfigFromPayload(config, item, key);

					// Get colors count for this item to determine gradient vs solid
					const colorsCount = itemConfig ? getColorsCount(itemConfig) : 1;

					return (
						<div
							key={index}
							className={cn(
								"[&>svg]:text-muted-foreground flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5",
								indicator === "dot" && "items-center",
								selected != null && selected !== item.dataKey && "opacity-30",
							)}
						>
							{formatter && item?.value !== undefined && item.name ? (
								formatter(item.value, item.name, item, index, item.payload)
							) : (
								<>
									{!hideIndicator && (
										<div
											className={cn("shrink-0 rounded-[2px]", {
												"h-2.5 w-2.5": indicator === "dot",
												"w-1": indicator === "line",
												"w-0 border-[1.5px] border-dashed bg-transparent!":
													indicator === "dashed",
												"my-0.5": nestLabel && indicator === "dashed",
											})}
											style={getIndicatorColorStyle(key, colorsCount)}
										/>
									)}
									{itemConfig?.icon && <itemConfig.icon />}
									<div
										className={cn(
											"flex flex-1 justify-between gap-4 leading-none",
											nestLabel ? "items-end" : "items-center",
										)}
									>
										<div className="grid gap-1.5">
											{nestLabel ? tooltipLabel : null}
											<span className="text-muted-foreground">
												{itemConfig?.label ?? item.name}
											</span>
										</div>
										{item.value != null && (
											<span className="text-foreground font-mono font-medium tabular-nums">
												{valueFormatter
													? valueFormatter(
															item.value,
															key,
															(item.payload ?? {}) as Record<string, unknown>,
														)
													: typeof item.value === "number"
														? item.value.toLocaleString()
														: String(item.value)}
											</span>
										)}
									</div>
								</>
							)}
						</div>
					);
				})}
			</div>
		</div>
	);
}

function getIndicatorColorStyle(
	dataKey: string,
	colorsCount: number,
): React.CSSProperties {
	if (colorsCount <= 1) {
		return { background: `var(--color-${dataKey}-0)` };
	}

	// Multiple colors: create linear gradient with evenly distributed stops
	const stops = Array.from({ length: colorsCount }, (_, index) => {
		const offset = (index / (colorsCount - 1)) * 100;
		return `var(--color-${dataKey}-${index}) ${offset}%`;
	}).join(", ");

	return { background: `linear-gradient(to right, ${stops})` };
}

const ChartTooltip = ({
	animationDuration = 200,
	...props
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip>) => (
	<RechartsPrimitive.Tooltip animationDuration={animationDuration} {...props} />
);

export { ChartTooltip, ChartTooltipContent };
export type { TooltipRoundness, TooltipVariant };

